def is_sverhy(mass, i, j):
	k = 0;
	for g in range(i, -1, -1):
		if mass[g][j] == 0:
			k+=1;
		if g != i and mass[g][j] == 1:
			return k;
	return k;

def is_snizy(mass, i, j, n):
	k = 0;
	for g in range(i, n):
		if mass[g][j] == 0:
			k+=1
		if g != i and mass[g][j] == 1:
			return k;
	return k;

def is_sprava(mass, i, j, m):
